def calculator(a, b, operator):
    if operator == '+':
        return a + b
    elif operator == '-':
        return a - b
    elif operator == '*':
        return a * b
    elif operator == '/':
        if b != 0:
            return a / b
        else:
            return "Error: Division by zero"
    else:
        return "Invalid operator"

def is_leap_year(year):
    if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
        return True
    else:
        return False

import math

def circle_area(radius):
    return math.pi * radius**2

def is_vowel(char):
    vowels = "aeiouAEIOU"
    return char in vowels

def absolute(num):
    if num >= 0:
        return num
    else:
        return -num

def max_of_three(a, b, c):
    if a >= b and a >= c:
        return a
    elif b >= a and b >= c:
        return b
    else:
        return c

def calculate_bmi(weight, height):
    bmi = weight / (height**2)
    return bmi

def min_of_two(a, b):
    if a < b:
        return a
    else:
        return b

def determine_grade(score):
    if score >= 90:
        return 'A'
    elif score >= 80:
        return 'B'
    elif score >= 70:
        return 'C'
    elif score >= 60:
        return 'D'
    else:
        return 'F'
